<?php
declare(strict_types=1);
putenv('RUMOHUB_ENABLED=0');putenv('RUMOHUB_BENEFITS=0');require dirname(__DIR__).'/app/bootstrap.php';
$g=Game::legacyCreate('Fixture perfil','São Paulo','SP','centroavante');$counts=array_fill_keys(array_column(Rules::HANDICAPS,'nome'),0);for($n=0;$n<10000;$n++)$counts[Probability::weighted(Rules::HANDICAPS)['nome']]++;
$total=array_sum(array_column(Rules::HANDICAPS,'peso'));$rows=[];foreach(Rules::HANDICAPS as $i=>$h){$expected=$h['peso']/$total;$actual=$counts[$h['nome']]/10000;if(abs($expected-$actual)>.025)throw new RuntimeException('Distribuição fora da tolerância');$effects=InitialProfile::effects($g,$h['efeitos']);foreach($effects as $key=>$v)if($v['after']-$v['before']!==$v['delta']||abs($v['delta'])>10)throw new RuntimeException('Efeito incoerente');$rows[]=['name'=>$h['nome'],'expected'=>$expected,'observed'=>$actual,'span'=>Wheel::segments(Rules::HANDICAPS)[$i]['span'],'effects'=>$effects];}
ob_start();InitialProfile::render($g);$html=ob_get_clean();if(!str_contains($html,'O que você pode ganhar ou perder')||substr_count($html,'→')!==12)throw new RuntimeException('Efeitos não apresentados');file_put_contents(dirname(__DIR__).'/Docs/estabilizacao-v04/perfil-inicial.json',json_encode(['draws'=>10000,'unchanged_weights'=>true,'unchanged_effects'=>true,'rows'=>$rows],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));echo "OK: 10.000 sorteios; áreas proporcionais e 12 efeitos antes/depois sem alterar pesos ou bônus.\n";
